import type { CharacterEthnicity, CharacterGender, CharacterView, GenerationAttempt } from "./database";

export type { CharacterEthnicity, CharacterGender, CharacterView, GenerationAttempt };
export type CharacterFaceSource = "upload" | "ai";

/** The 4 real, model-generated angles — excludes "composite", which is
 * never generated by a model (it's the server-composited merge of these
 * same 4 — see compose-sheet.ts) and so never appears in CHARACTER_VIEWS
 * or needs a prompt of its own. */
export type GeneratedCharacterView = Exclude<CharacterView, "composite">;

export const CHARACTER_MIN_AGE = 12;
export const CHARACTER_MAX_AGE = 80;
export const CHARACTER_DEFAULT_AGE = 22;

/** The full turnaround sequence a character sheet cycles through — a
 * sheet with `count` images uses the first `count` of these, in order.
 * Matches the product's reference sheet exactly: 2 full-body angles
 * (front/back, head-to-toe) plus 4 close-ups with distinct
 * expressions/angles — composeCharacterSheet() (compose-sheet.ts) lays
 * front/back out large on the left and the 4 close-ups as a 2×2 grid on
 * the right, padded to a fixed 16:9 sheet. Front/back come first so a
 * sheet with `count` &lt; 6 still includes both full-body angles before
 * any close-up variant drops off. "side" (the old single 3/4 full-body
 * angle) is deliberately NOT included here any more — see CharacterView
 * in types/database.ts for why it's kept as a legacy-only value. */
export const CHARACTER_VIEWS: GeneratedCharacterView[] = [
  "front",
  "back",
  "portrait",
  "portrait_side",
  "portrait_profile",
  "portrait_detail",
];

export const CHARACTER_VIEW_LABEL: Record<CharacterView, string> = {
  portrait: "Cận mặt — nhìn thẳng",
  portrait_side: "Cận mặt — nghiêng 3/4, cười nhẹ",
  portrait_profile: "Cận mặt — nghiêng hẳn, nghiêm túc",
  portrait_detail: "Cận mặt — cận cảnh, tự tin",
  front: "Toàn thân chính diện",
  side: "Toàn thân nghiêng 3/4",
  back: "Toàn thân phía sau",
  composite: "Bảng nhân vật tổng hợp",
};

export const CHARACTER_GENDER_LABEL: Record<CharacterGender, string> = {
  male: "Nam",
  female: "Nữ",
};

export const CHARACTER_ETHNICITY_LABEL: Record<CharacterEthnicity, string> = {
  vietnamese: "Người Việt",
  asian: "Châu Á",
  european: "Châu Âu",
};

export interface Character {
  id: string;
  workspaceId: string;
  displayName: string;
  tagName: string;
  gender: CharacterGender;
  ethnicity: CharacterEthnicity;
  age: number;
  faceSource: CharacterFaceSource;
  /** Short-lived signed URL, resolved server-side on every read — never
   * persisted client-side beyond the current page load (same convention
   * as every other Storage-backed URL in this app). Null when the
   * underlying object can't be resolved (e.g. migration not applied yet,
   * or the row predates a successful upload). */
  faceUrl: string | null;
  faceLocked: boolean;
  consentConfirmed: boolean;
  createdAt: string;
}

export interface CharacterSheetViewItem {
  view: CharacterView;
  jobId: string;
  status: "queued" | "processing" | "succeeded" | "failed" | "cancelled";
  url: string | null;
  width: number | null;
  height: number | null;
  isDemo: boolean;
  savedAssetId: string | null;
  error: string | null;
  prompt: string;
  requestedModel: string | null;
  finalModel: string | null;
  /** Non-empty when the resolved model had to adjust the request (e.g.
   * "model này chưa hỗ trợ ảnh tham chiếu khuôn mặt") — surfaced as-is,
   * never hidden, per the product rule that adjustments are always shown. */
  attempts: GenerationAttempt[];
}

export interface CharacterSheet {
  sheetId: string;
  characterId: string;
  createdAt: string;
  views: CharacterSheetViewItem[];
}
